        static readonly Dictionary<string, GraphicsPath> parsed = new Dictionary<string, GraphicsPath>();

        public static bool Has(string name) { return Data.ContainsKey(name); }
        public static IEnumerable<string> Names { get { return Data.Keys; } }

        // Draws the icon centred in r at size px (the 24-unit grid scaled to px), stroked in c.
        public static void Draw(Graphics g, string name, Rectangle r, int px, Color c)
        {
            GraphicsPath p = Path(name);
            if (p == null) return;
            float k = px / 24f;
            GraphicsState st = g.Save();
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.TranslateTransform(r.X + (r.Width - px) / 2f, r.Y + (r.Height - px) / 2f);
            g.ScaleTransform(k, k);
            using (var pen = new Pen(c, px >= 20 ? 2f : 2.2f) { StartCap = LineCap.Round, EndCap = LineCap.Round, LineJoin = LineJoin.Round }) g.DrawPath(pen, p);
            g.Restore(st);
        }

        static GraphicsPath Path(string name)
        {
            GraphicsPath p;
            if (parsed.TryGetValue(name, out p)) return p;
            string[] ds;
            if (!Data.TryGetValue(name, out ds)) return null;
            p = new GraphicsPath();
            foreach (string d in ds) Parse(p, d);
            parsed[name] = p;
            return p;
        }

        // M x y, L x y, H x, V y, C x1 y1 x2 y2 x y, Z (absolute only).
        public static void Parse(GraphicsPath p, string d)
        {
            var tok = new List<string>();
            foreach (System.Text.RegularExpressions.Match m in System.Text.RegularExpressions.Regex.Matches(d, @"[MLHVCZmlhvcz]|-?\d*\.?\d+(?:e-?\d+)?"))
                tok.Add(m.Value);
            float x = 0, y = 0, sx = 0, sy = 0;
            char cmd = 'M';
            int i = 0;
            Func<float> num = () => float.Parse(tok[i++], CultureInfo.InvariantCulture);
            while (i < tok.Count)
            {
                if (char.IsLetter(tok[i][0])) cmd = tok[i++][0];
                switch (cmd)
                {
                    case 'M': x = num(); y = num(); p.StartFigure(); sx = x; sy = y; cmd = 'L'; break;
                    case 'L': { float nx = num(), ny = num(); p.AddLine(x, y, nx, ny); x = nx; y = ny; break; }
                    case 'H': { float nx = num(); p.AddLine(x, y, nx, y); x = nx; break; }
                    case 'V': { float ny = num(); p.AddLine(x, y, x, ny); y = ny; break; }
                    case 'C':
                    {
                        float x1 = num(), y1 = num(), x2 = num(), y2 = num(), nx = num(), ny = num();
                        p.AddBezier(x, y, x1, y1, x2, y2, nx, ny);
                        x = nx; y = ny;
                        break;
                    }
                    case 'Z': p.CloseFigure(); x = sx; y = sy; break;
                    default: throw new FormatException("unsupported path command " + cmd);
                }
            }
        }
